#!/usr/bin/env bash
set -euo pipefail

# Test: onboarding-guard.sh allows onboarding through, blocks work
# Generated by /qa on 2026-04-10 for PR #529 regression fix
# Covers: .claude/hooks/onboarding-guard.sh — VERIFY state, escaped quotes, Edit/Write gates

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
GUARD="$SCRIPT_DIR/.claude/hooks/onboarding-guard.sh"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; }

# --- Setup: temp dir with onboarding_complete: false ---
TMPDIR=$(mktemp -d)
trap 'rm -rf "$TMPDIR"' EXIT

cat > "$TMPDIR/.egregore-state.json" << 'EOF'
{
  "github_username": "testuser",
  "github_name": "Test User",
  "onboarding_complete": false,
  "usage_type": "founder_group"
}
EOF

# Helper: pipe JSON to guard, return exit code
run_guard() {
  echo "$1" | CLAUDE_PROJECT_DIR="$TMPDIR" bash "$GUARD" 2>/dev/null
  return $?
}

echo "Testing: onboarding-guard.sh"
echo ""

# ============================================================
echo "== Bash commands (all should be ALLOWED) =="
# ============================================================

# VERIFY state: .env reads
run_guard '{"tool_name":"Bash","command":"TOKEN=$(grep GITHUB_TOKEN .env) && echo ok"}' \
  && pass "VERIFY: .env reads" \
  || fail "VERIFY: .env reads BLOCKED" "Guard must allow all Bash during onboarding"

# VERIFY state: egregore.json reads
run_guard '{"tool_name":"Bash","command":"jq -r .api_url egregore.json"}' \
  && pass "VERIFY: egregore.json reads" \
  || fail "VERIFY: egregore.json reads BLOCKED"

# VERIFY state: memory symlink check
run_guard '{"tool_name":"Bash","command":"test -L memory && echo ok"}' \
  && pass "VERIFY: memory symlink check" \
  || fail "VERIFY: memory symlink check BLOCKED"

# State write with escaped quotes (the regex truncation bug)
run_guard '{"tool_name":"Bash","command":"jq --arg ts \"2026\" \".onboarding = {\\\"phase\\\": \\\"orient\\\"}\" .egregore-state.json > .tmp"}' \
  && pass "State write: jq with escaped quotes" \
  || fail "State write: jq with escaped quotes BLOCKED" "Regex must handle escaped quotes"

# git config
run_guard '{"tool_name":"Bash","command":"git config user.name"}' \
  && pass "git config" \
  || fail "git config BLOCKED"

# graph.sh
run_guard '{"tool_name":"Bash","command":"bash bin/graph.sh query MATCH (p:Person) RETURN p"}' \
  && pass "graph.sh" \
  || fail "graph.sh BLOCKED"

# memory commit + push
run_guard '{"tool_name":"Bash","command":"cd memory && git add -A && git commit -m test && git push"}' \
  && pass "memory git operations" \
  || fail "memory git operations BLOCKED"

# telemetry
run_guard '{"tool_name":"Bash","command":"bash bin/telemetry.sh emit onboarding_complete"}' \
  && pass "telemetry.sh" \
  || fail "telemetry.sh BLOCKED"

echo ""

# ============================================================
echo "== Non-Bash tools that should be ALLOWED =="
# ============================================================

run_guard '{"tool_name":"Skill","skill":"onboarding"}' \
  && pass "Skill tool" \
  || fail "Skill tool BLOCKED"

run_guard '{"tool_name":"Read","file_path":"/some/file.txt"}' \
  && pass "Read tool" \
  || fail "Read tool BLOCKED"

run_guard '{"tool_name":"Grep","pattern":"test"}' \
  && pass "Grep tool" \
  || fail "Grep tool BLOCKED"

run_guard '{"tool_name":"AskUserQuestion","question":"Name?"}' \
  && pass "AskUserQuestion" \
  || fail "AskUserQuestion BLOCKED"

echo ""

# ============================================================
echo "== Edit/Write to onboarding files (should be ALLOWED) =="
# ============================================================

run_guard '{"tool_name":"Write","file_path":"'"$TMPDIR"'/.egregore-state.json"}' \
  && pass "Write .egregore-state.json" \
  || fail "Write .egregore-state.json BLOCKED"

run_guard '{"tool_name":"Edit","file_path":"'"$TMPDIR"'/memory/people/testuser.md"}' \
  && pass "Edit memory/people/" \
  || fail "Edit memory/people/ BLOCKED"

run_guard '{"tool_name":"Write","file_path":"'"$TMPDIR"'/memory/handoffs/2026-04/test.md"}' \
  && pass "Write memory/handoffs/" \
  || fail "Write memory/handoffs/ BLOCKED"

run_guard '{"tool_name":"Edit","file_path":"'"$TMPDIR"'/egregore.md"}' \
  && pass "Edit egregore.md" \
  || fail "Edit egregore.md BLOCKED"

echo ""

# ============================================================
echo "== Edit/Write to NON-onboarding files (should be BLOCKED) =="
# ============================================================

run_guard '{"tool_name":"Write","file_path":"'"$TMPDIR"'/src/app.js"}' \
  && fail "Write src/app.js ALLOWED" "Should be blocked — not an onboarding file" \
  || pass "Write src/app.js blocked"

run_guard '{"tool_name":"Edit","file_path":"'"$TMPDIR"'/bin/session-start.sh"}' \
  && fail "Edit bin/session-start.sh ALLOWED" "Should be blocked" \
  || pass "Edit bin/session-start.sh blocked"

run_guard '{"tool_name":"Write","file_path":"'"$TMPDIR"'/CLAUDE.md"}' \
  && fail "Write CLAUDE.md ALLOWED" "Should be blocked" \
  || pass "Write CLAUDE.md blocked"

echo ""

# ============================================================
echo "== EnterWorktree (should be BLOCKED) =="
# ============================================================

run_guard '{"tool_name":"EnterWorktree","name":"some-feature"}' \
  && fail "EnterWorktree ALLOWED" "Should be blocked during onboarding" \
  || pass "EnterWorktree blocked"

echo ""

# ============================================================
echo "== Fast path: onboarding_complete=true (everything allowed) =="
# ============================================================

cat > "$TMPDIR/.egregore-state.json" << 'EOF'
{
  "github_username": "testuser",
  "onboarding_complete": true
}
EOF

run_guard '{"tool_name":"Write","file_path":"'"$TMPDIR"'/src/app.js"}' \
  && pass "Write src/app.js (onboarding complete)" \
  || fail "Write src/app.js BLOCKED after onboarding complete"

run_guard '{"tool_name":"EnterWorktree","name":"feature"}' \
  && pass "EnterWorktree (onboarding complete)" \
  || fail "EnterWorktree BLOCKED after onboarding complete"

echo ""

# ============================================================
echo "== Edge: no state file (fail-open) =="
# ============================================================

rm -f "$TMPDIR/.egregore-state.json"

run_guard '{"tool_name":"Write","file_path":"'"$TMPDIR"'/anything.js"}' \
  && pass "Write allowed (no state file)" \
  || fail "Write BLOCKED (no state file)" "Should fail-open when state file missing"

echo ""

# --- Summary ---
echo "─────────────────────────────────"
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
